// server.js
const express = require('express');
const cors = require('cors');
const paypal = require('@paypal/checkout-server-sdk');
const dotenv = require('dotenv');
const path = require('path');

dotenv.config();

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(express.json());

// PayPal Environment Configuration
function environment() {
    const clientId = process.env.PAYPAL_CLIENT_ID;
    const clientSecret = process.env.PAYPAL_CLIENT_SECRET;
    
    // Use Sandbox for testing, Live for production
    return new paypal.core.SandboxEnvironment(clientId, clientSecret);
}

function client() {
    return new paypal.core.PayPalHttpClient(environment());
}

// ============================================
// ENDPOINT 1: Create Payment
// ============================================
app.post('/api/create-payment', async (req, res) => {
    try {
        const request = new paypal.orders.OrdersCreateRequest();
        request.requestBody({
            intent: 'CAPTURE',
            purchase_units: [{
                amount: {
                    currency_code: 'USD',
                    value: '2.99' // Your price
                },
                description: 'Image Download Access'
            }],
            application_context: {
                return_url: 'http://localhost:3000/success',
                cancel_url: 'http://localhost:3000/cancel'
            }
        });

        const order = await client().execute(request);
        
        res.json({
            success: true,
            id: order.result.id
        });
    } catch (error) {
        console.error('Error creating payment:', error);
        res.status(500).json({
            success: false,
            error: error.message
        });
    }
});

// ============================================
// ENDPOINT 2: Verify Payment
// ============================================
app.post('/api/verify-payment', async (req, res) => {
    try {
        const { orderID } = req.body;
        
        // Capture the payment
        const request = new paypal.orders.OrdersCaptureRequest(orderID);
        request.requestBody({});
        
        const capture = await client().execute(request);
        
        // Check if payment was successful
        if (capture.result.status === 'COMPLETED') {
            // Generate a signed URL for the image
            // In production, this would be a signed URL from S3 or similar
            const imageUrl = generateSignedUrl('your-image.jpg');
            
            res.json({
                success: true,
                message: 'Payment verified successfully',
                downloadUrl: imageUrl,
                transactionId: capture.result.id
            });
        } else {
            res.status(400).json({
                success: false,
                error: 'Payment not completed'
            });
        }
    } catch (error) {
        console.error('Error verifying payment:', error);
        res.status(500).json({
            success: false,
            error: error.message
        });
    }
});

// ============================================
// ENDPOINT 3: Download Image
// ============================================
app.get('/api/download', (req, res) => {
    // Validate the signed URL token here
    // For now, serving a sample image
    
    const imagePath = path.join(__dirname, 'public', 'sample-image.jpg');
    res.sendFile(imagePath, (err) => {
        if (err) {
            res.status(404).json({
                success: false,
                error: 'Image not found'
            });
        }
    });
});

// Helper function to generate signed URL
function generateSignedUrl(filename) {
    // In production, implement proper signed URL generation
    // For now, return a simple URL
    return `http://localhost:${PORT}/api/download?file=${filename}`;
}

// ============================================
// Test endpoints
// ============================================
app.get('/health', (req, res) => {
    res.json({ status: 'Server is running' });
});

// Start server
app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
    console.log(`Create payment endpoint: POST http://localhost:${PORT}/api/create-payment`);
    console.log(`Verify payment endpoint: POST http://localhost:${PORT}/api/verify-payment`);
    console.log(`Download endpoint: GET http://localhost:${PORT}/api/download`);
});